package com.cinebook.config;
import com.cinebook.auth.*; import com.cinebook.catalog.*; import com.cinebook.booking.*; import org.springframework.boot.ApplicationRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.core.env.Environment; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Configuration
public class DevelopmentSeed {
 @Bean @ConditionalOnProperty(name="app.seed.enabled", havingValue="true", matchIfMissing=true) ApplicationRunner seedDevelopmentData(UserRepository users,MovieRepository movies,TheatreRepository theatres,ScreenRepository screens,SeatRepository seats,ShowtimeRepository shows,ShowSeatRepository showSeats,CouponRepository coupons,PasswordEncoder encoder,Environment environment){return args->{if(Arrays.asList(environment.getActiveProfiles()).contains("prod")){System.out.println("CineBook seed skipped: production profile is active.");return;}seed(users,movies,theatres,screens,seats,shows,showSeats,coupons,encoder);};}
 @Transactional void seed(UserRepository users,MovieRepository movies,TheatreRepository theatres,ScreenRepository screens,SeatRepository seats,ShowtimeRepository shows,ShowSeatRepository showSeats,CouponRepository coupons,PasswordEncoder encoder){
  if(movies.count()>0)return;
  UserAccount admin=account(users,encoder,"admin@cinebook.local","CineBookDemo!2026","CineBook Admin",Role.ADMIN);
  account(users,encoder,"ops@cinebook.local","CineBookDemo!2026","Operations Demo",Role.OPERATIONS);
  UserAccount partner=account(users,encoder,"partner@cinebook.local","CineBookDemo!2026","Theatre Partner",Role.THEATRE_PARTNER);
  account(users,encoder,"customer@cinebook.local","CineBookDemo!2026","Demo Customer",Role.CUSTOMER);
  List<Movie> catalog=movies.saveAll(List.of(
   new Movie("Interstellar","A team travels beyond the limits of our world to search for humanity's next home.","https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxmlNBv4.jpg","https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=1800&q=85",169,"English","Sci-Fi,Adventure,Drama","UA",LocalDate.of(2014,11,7),8.7),
   new Movie("Dune: Part Two","Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family.","https://image.tmdb.org/t/p/w500/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg","https://images.unsplash.com/photo-1462331940025-496dfbfc7564?auto=format&fit=crop&w=1800&q=85",166,"English","Sci-Fi,Adventure,Drama","UA",LocalDate.of(2024,3,1),8.5),
   new Movie("The Batman","A detective follows a trail of corruption and a killer's clues through a rain-soaked Gotham.","https://image.tmdb.org/t/p/w500/74xTEgt7R36Fpooo50r9T25onhq.jpg","https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=1800&q=85",176,"English","Action,Crime,Drama","UA",LocalDate.of(2022,3,4),7.8),
   new Movie("Spider-Man: Across the Spider-Verse","Miles Morales swings into a multiverse adventure with a remarkable team of Spider-heroes.","https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xjilm2M.jpg","https://images.unsplash.com/photo-1534796636912-3b95b3ab5986?auto=format&fit=crop&w=1800&q=85",140,"English","Animation,Action,Adventure","U",LocalDate.of(2023,6,2),8.6),
   new Movie("Drishyam 2","A family man must protect his family as an old case threatens to resurface.","https://image.tmdb.org/t/p/w500/7uJf8sW5p1J7Jk9cP1k2JH4yXyI.jpg","https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=1800&q=85",140,"Hindi","Thriller,Crime,Drama","UA",LocalDate.of(2022,11,18),8.2),
   new Movie("The Grand Budapest Hotel","A legendary concierge and his young protégé become embroiled in a caper at a storied European hotel.","https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg","https://images.unsplash.com/photo-1511818966892-d7d671e672a2?auto=format&fit=crop&w=1800&q=85",99,"English","Comedy,Adventure","U",LocalDate.of(2014,3,28),8.1)
  ));
  List<Theatre> venueList=new ArrayList<>();String[][] venueData={{"PVR Pacific Mall","Dehradun","Pacific Mall, Rajpur Road, Dehradun"},{"Cinepolis City Centre","Dehradun","City Centre, Haridwar Road, Dehradun"},{"Regal Cinema","Mussoorie","Library Chowk, Mussoorie"}};
  for(String[] v:venueData){Theatre t=theatres.save(new Theatre(v[0],v[1],v[2],partner));venueList.add(t);for(int n=1;n<=3;n++){Screen sc=screens.save(new Screen(t,"Screen "+n,8,10));List<Seat> screenSeats=new ArrayList<>();for(int row=0;row<8;row++){String label=String.valueOf((char)('A'+row));for(int col=1;col<=10;col++){Seat.Type type=row>=6?Seat.Type.RECLINER:(row>=4?Seat.Type.PREMIUM:Seat.Type.STANDARD);screenSeats.add(new Seat(sc,label,col,type,row==7&&(col==1||col==2)));}}seats.saveAll(screenSeats);}}
  ZoneId zone=ZoneId.of("Asia/Kolkata");LocalDate today=LocalDate.now(zone);int showCount=0;
  for(int theatreIndex=0;theatreIndex<venueList.size();theatreIndex++){Theatre t=venueList.get(theatreIndex);List<Screen> localScreens=screens.findAllByTheatreId(t.getId());for(int movieIndex=0;movieIndex<catalog.size();movieIndex++){Screen screen=localScreens.get(movieIndex%localScreens.size());for(int day=1;day<=3;day++){LocalTime time=List.of(LocalTime.of(11,30),LocalTime.of(15,30),LocalTime.of(19,30)).get((movieIndex/3+theatreIndex)%3);ZonedDateTime start=today.plusDays(day).atTime(time).atZone(zone);Showtime sh=shows.save(new Showtime(catalog.get(movieIndex),screen,start.toInstant(),start.plusMinutes(catalog.get(movieIndex).getDurationMinutes()+20).toInstant(),new BigDecimal(theatreIndex==2?"220.00":"250.00")));List<ShowSeat> inventory=new ArrayList<>();for(Seat seat:seats.findAllByScreenIdOrderByRowLabelAscSeatNumberAsc(screen.getId())){BigDecimal price=switch(seat.getType()){case STANDARD->sh.getBasePrice();case PREMIUM->sh.getBasePrice().multiply(new BigDecimal("1.25")).setScale(2,java.math.RoundingMode.HALF_UP);case RECLINER->sh.getBasePrice().multiply(new BigDecimal("1.60")).setScale(2,java.math.RoundingMode.HALF_UP);};inventory.add(new ShowSeat(sh,seat,price));}showSeats.saveAll(inventory);showCount++;}}}
  if(coupons.count()==0){Instant start=Instant.now().minusSeconds(86400);coupons.save(new Coupon("WELCOME10","Welcome discount — 10% off ticket subtotal",new BigDecimal("10.00"),new BigDecimal("100.00"),new BigDecimal("200.00"),start,Instant.now().plus(Duration.ofDays(365)),500));coupons.save(new Coupon("CINE15","CineBook treat — 15% off ticket subtotal",new BigDecimal("15.00"),new BigDecimal("150.00"),new BigDecimal("350.00"),start,Instant.now().plus(Duration.ofDays(90)),200));}
  System.out.println("CineBook AI development seed: "+catalog.size()+" movies, "+venueList.size()+" theatres, "+showCount+" showtimes. Demo accounts use password CineBookDemo!2026 (local only).");
 }
 private UserAccount account(UserRepository users,PasswordEncoder encoder,String email,String password,String name,Role role){return users.findByEmailIgnoreCase(email).orElseGet(()->users.save(new UserAccount(email,encoder.encode(password),name,role)));}
}
